#!/usr/bin/env python3
"""Remove JavaScript (XSS vectors) from an HTML file, in place.

Usage: python3 filter.py FILE.html

The file is rewritten with all script-executing constructs removed while
everything else (formatting, whitespace, tables, headings, harmless
attributes, comments, text) is preserved byte-for-byte wherever possible:
start tags are re-emitted verbatim unless one of their attributes had to be
dropped or cleaned.
"""

import html
import io
import re
import sys
from html.parser import HTMLParser

# ---------------------------------------------------------------- constants

# Elements whose entire content is script / plugin code.
DROP_ELEMENTS = frozenset({"script"})

# Elements that are only ever script/plugin hosts once their dangerous
# attributes are gone -- kept, just sanitized (see attribute handling).

# Attributes that hold a URL and therefore may hold a "javascript:" URL.
URL_ATTRS = frozenset({
    "href", "src", "action", "formaction", "background", "dynsrc",
    "lowsrc", "poster", "data", "codebase", "cite", "longdesc",
    "usemap", "profile", "manifest", "archive", "classid", "ping",
    "xlink:href", "xml:base", "folder", "to", "from", "values",
    "attributevalue", "srcset", "imagesrcset", "content",
})

# Attributes that are dangerous no matter their value.
BAD_ATTRS = frozenset({
    "srcdoc",        # inline HTML document -> can contain scripts
    "seekSegmentTime".lower(),
    "datasrc", "datafld", "dataformatas",   # legacy IE data binding
    "http-equiv",    # only when it is a refresh with a bad URL (handled)
})

# URL schemes that can execute code.
BAD_SCHEMES = (
    "javascript", "vbscript", "livescript", "jscript", "ecmascript",
    "mocha", "about", "behavior", "view-source", "moz-binding",
)

# data: URLs we accept (inert images only; svg/html/xml can script).
SAFE_DATA_RE = re.compile(
    r"^data:image/(?:png|jpe?g|gif|webp|bmp|x-icon|vnd\.microsoft\.icon)[;,]",
    re.I,
)

# CSS constructs that execute script in one browser or another.
CSS_BAD_RE = re.compile(
    r"(?:expression\s*\(|-moz-binding\s*:|behavior\s*:|"
    r"@import|javascript\s*:|vbscript\s*:|\\0*6a\s*avascript)",
    re.I,
)

SVG_ANIM_ELEMENTS = frozenset({"animate", "set", "animatetransform",
                               "animatemotion", "handler"})

COMMENT_BAD_RE = re.compile(
    r"(?:<\s*script|javascript\s*:|vbscript\s*:|\bon[a-z]{3,}\s*=|\[if\b|"
    r"<\s*i?frame|<\s*object|<\s*embed|<\s*svg|<\s*img)", re.I)


# ------------------------------------------------------------------ helpers

def _decode_all(value):
    """Fully decode HTML entities (repeatedly) and drop invisible junk."""
    prev = None
    cur = value
    for _ in range(6):
        if cur == prev:
            break
        prev = cur
        cur = html.unescape(cur)
    # Browsers ignore control characters / NULs inside the scheme.
    cur = re.sub(r"[\x00-\x20\x7f�﻿​-‏  ]", "", cur)
    return cur


def is_dangerous_url(value):
    """True if the (raw, possibly entity-encoded) URL can run script."""
    if value is None:
        return False
    cleaned = _decode_all(value).lower()
    if not cleaned:
        return False
    scheme_match = re.match(r"^([a-z0-9+.\-]+):", cleaned)
    if scheme_match:
        scheme = scheme_match.group(1)
        if scheme in BAD_SCHEMES:
            return True
        if scheme == "data":
            if not SAFE_DATA_RE.match(_decode_all(value).strip()):
                return True
    # "&{alert(1)};" (Netscape entity script) and CSS-ish payloads.
    if "&{" in cleaned:
        return True
    if CSS_BAD_RE.search(cleaned):
        return True
    return False


def clean_style(value):
    """Return a sanitized style attribute / stylesheet body, or '' if empty."""
    if value is None:
        return None
    if not CSS_BAD_RE.search(_decode_all(value)):
        return value
    out = []
    for decl in value.split(";"):
        if CSS_BAD_RE.search(_decode_all(decl)):
            continue
        out.append(decl)
    result = ";".join(out)
    if CSS_BAD_RE.search(_decode_all(result)):
        return ""
    return result


def clean_stylesheet(text):
    """Drop dangerous declarations/rules from a <style> element body."""
    if not CSS_BAD_RE.search(_decode_all(text)):
        return text
    # Remove @import rules and any declaration containing a bad construct.
    text = re.sub(r"@import[^;}]*;?", "", text, flags=re.I)
    text = re.sub(r"[a-zA-Z\-]+\s*:\s*[^;{}]*"
                  r"(?:expression\s*\(|javascript\s*:|vbscript\s*:|"
                  r"url\s*\(\s*['\"]?\s*(?:javascript|vbscript|data)\s*:)"
                  r"[^;{}]*;?", "", text, flags=re.I)
    text = re.sub(r"(?:-moz-binding|behavior)\s*:[^;{}]*;?", "", text, flags=re.I)
    if CSS_BAD_RE.search(_decode_all(text)):
        return ""
    return text


