    m = re.match(r"<\s*([^\s/>]+)", raw or "")
    return m.group(1) if m else fallback


# ------------------------------------------------------------------- filter

class JSFilter(HTMLParser):
    def __init__(self):
        # convert_charrefs=False so text entities are emitted unchanged.
        super().__init__(convert_charrefs=False)
        self.out = io.StringIO()
        self.skip_depth = 0          # inside a dropped element
        self.skip_tag = None
        self.in_style = False

    # -- output helper
    def w(self, text):
        if self.skip_depth == 0:
            self.out.write(text)

    # -- attribute sanitizing
    def _filter_attrs(self, tag, attrs):
        """Return (kept_attrs, changed, drop_element)."""
        kept = []
        changed = False
        drop_element = False
        attr_map = {k.lower(): (v or "") for k, v in attrs}

