                changed = True
                continue
            if lname in ("srcdoc", "datasrc", "datafld", "dataformatas",
                         "seeksegmenttime"):
                changed = True
                continue
            if lname == "style":
                new = clean_style(value)
                if new != value:
                    changed = True
                    if not (new or "").strip():
                        continue
                    value = new
                kept.append((name, value))
                continue
            if lname == "attributename":
                low = _decode_all(value or "").strip().lower()
                if low.startswith("on") or low in ("href", "xlink:href",
                                                   "src", "style", "action",
                                                   "formaction"):
                    drop_element = True
                    changed = True
                    continue
            if lname == "content" and tag == "meta":
                http_equiv = attr_map.get("http-equiv", "").strip().lower()
