                                  "content-type", "x-dns-prefetch-control"):
                    payload = value or ""
                    url_part = payload
                    m = re.search(r"url\s*=\s*(.*)$", payload,
                                  re.I | re.S)
                    if m:
                        url_part = m.group(1).strip().strip("'\"")
                    if is_dangerous_url(url_part) or is_dangerous_url(payload):
                        changed = True
                        continue
                kept.append((name, value))
                continue
            if lname in URL_ATTRS or lname.endswith(":href") or \
                    lname.endswith("src"):
                if is_dangerous_url(value):
                    changed = True
                    if tag in SVG_ANIM_ELEMENTS:
                        drop_element = True
                    continue
                if lname in ("srcset", "imagesrcset") and value:
                    if any(is_dangerous_url(part.strip().split(" ")[0])
                           for part in value.split(",")):
                        changed = True
                        continue
            elif value and is_dangerous_url(value) and \
                    tag in SVG_ANIM_ELEMENTS:
                # <animate values="javascript:...">
                drop_element = True
                changed = True
                continue

            kept.append((name, value))

        return kept, changed, drop_element

    @staticmethod
    def _render_tag(raw, tag, attrs, self_closing):
        name = _original_tag_name(raw, tag)
        parts = ["<", name]
        for aname, avalue in attrs:
            if avalue is None:
                parts.append(" " + aname)
            else:
                parts.append(' %s="%s"' % (aname, html.escape(avalue,
                                                              quote=True)))
        parts.append(" />" if self_closing else ">")
        return "".join(parts)

    def _handle_open(self, tag, attrs, self_closing):
        raw = self.get_starttag_text() or ""

        if self.skip_depth:
            if tag == self.skip_tag and not self_closing:
                self.skip_depth += 1
            return

        if tag in DROP_ELEMENTS:
            if not self_closing:
                self.skip_depth = 1
                self.skip_tag = tag
            return

        kept, changed, drop_element = self._filter_attrs(tag, attrs)
        if drop_element:
            if not self_closing:
                self.skip_depth = 1
                self.skip_tag = tag
            return

        if tag == "style":
            self.in_style = True

        if changed:
            self.w(self._render_tag(raw, tag, kept,
                                    self_closing or raw.rstrip().endswith("/>")))
        else:
            self.w(raw)

    # -- HTMLParser hooks
    def handle_starttag(self, tag, attrs):
        self._handle_open(tag, attrs, False)

    def handle_startendtag(self, tag, attrs):
        self._handle_open(tag, attrs, True)

    def handle_endtag(self, tag):
        if self.skip_depth:
            if tag == self.skip_tag:
                self.skip_depth -= 1
                if self.skip_depth == 0:
                    self.skip_tag = None
            return
        if tag in DROP_ELEMENTS:
            return
        if tag == "style":
            self.in_style = False
        self.w("</%s>" % tag)

    def handle_data(self, data):
        if self.skip_depth:
            return
        if self.in_style:
            self.w(clean_stylesheet(data))
            return
        self.w(data)

    def handle_entityref(self, name):
        self.w("&%s;" % name)

    def handle_charref(self, name):
        self.w("&#%s;" % name)

    def handle_comment(self, data):
        if self.skip_depth:
            return
        # Conditional comments and comment-smuggled scripts execute; drop
        # only those, keep ordinary comments verbatim.
        if COMMENT_BAD_RE.search(_decode_all(data)):
            return
        self.w("<!--%s-->" % data)

    def handle_decl(self, decl):
        self.w("<!%s>" % decl)

    def unknown_decl(self, data):
        self.w("<![%s]>" % data)

    def handle_pi(self, data):
        # <?xml:namespace ...> / <?import ...> were IE script vectors.
        if re.search(r"import|namespace|stylesheet", data, re.I):
            return
        self.w("<?%s>" % data)


# --------------------------------------------------------------------- main

def sanitize(text):
    parser = JSFilter()
    parser.feed(text)
    parser.close()
    result = parser.out.getvalue()
    # Defence in depth: nothing that looks like a script element or an
    # inline handler may survive in the output.
    result = re.sub(r"<\s*/?\s*script\b[^>]*>?", "", result, flags=re.I)
    return result


def main(argv):
    if len(argv) < 2:
        sys.stderr.write("usage: %s FILE.html\n" % argv[0])
        return 2
    path = argv[1]
    with open(path, "rb") as fh:
        raw = fh.read()
    for encoding in ("utf-8", "latin-1"):
        try:
            text = raw.decode(encoding)
            break
        except UnicodeDecodeError:
            continue
    else:  # pragma: no cover
        encoding = "utf-8"
        text = raw.decode("utf-8", "replace")

    cleaned = sanitize(text)

    with open(path, "wb") as fh:
        fh.write(cleaned.encode(encoding, "xmlcharrefreplace"))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

